    /**
    * Calls:
    * (200) POST:/WebGoat/SqlInjection/attack2
    * Found 1 potential fault of type-code 200
    */
    @Test @Timeout(60)
    fun test_71_postOnSqlInjectionAttack2WithQueryParamReturnsMismatchResponseWithSchema()  {
        
        val cookies_userB : Map<String,String> = given()
            .contentType("application/x-www-form-urlencoded")
            .body("username=userbb&password=userBB")
            .post("${baseUrlOfSut}/WebGoat/login")
            .then().extract().cookies()
            
        
        // Fault200. Schema Violation: Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.body.schema.type [Path '/feedbackArgs'] Instance type (null) does not match any allowed primitive type (allowed: ["array"])
        given().accept("*/*")
                .cookies(cookies_userB)
                .noContentType()
                .post("${baseUrlOfSut}/WebGoat/SqlInjection/attack2?query=xqE")
                .then()
                .statusCode(200)
                .assertThat()
                .contentType("application/json")
                .body("'assignment'", containsString("SqlInjectionLesson2"))
                .body("'attemptWasMade'", equalTo(true))
                .body("'feedback'", containsString("Something went wrong! You got no results, check your SQL Statement and the table above."))
                .body("'feedbackArgs'", nullValue())
                .body("'lessonCompleted'", equalTo(false))
                .body("'output'", containsString("unexpected token: XQE"))
                .body("'outputArgs'", nullValue())
    }
    
    
